// Package profile stores lightweight user profiles for gnomemepad.
// Independent of pad versions â€” upgrade this realm without redeploying markets.
//
//	SetProfile(displayName, bio, uri) â€” EOA only, per caller address
//	GetProfile(addr) â†’ name|bio|uri|updatedHeight
package profile

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	maxNameLen = 48
	maxBioLen  = 280
	maxURILen  = 200
)

// Profile is one user's public card (all fields exported for LaunchInfo-style reads).
type Profile struct {
	Name    string
	Bio     string
	URI     string
	Updated int64 // block height
}

var (
	// byAddr: address string -> *Profile
	byAddr avl.Tree
	inited bool
)

// Init is optional (no-op state). Kept for deploy symmetry with hub/pad.
func Init(cur realm) {
	if inited {
		panic("profile: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("profile: EOA only")
	}
	inited = true
	byAddr = avl.Tree{}
	chain.Emit("Init", "by", cur.Previous().Address().String())
}

func ensure() {
	// Lazy: allow SetProfile before Init for simpler UX; Init still recommended.
	if !inited {
		byAddr = avl.Tree{}
		inited = true
	}
}

func sanitizeText(s string, max int) string {
	s = strings.TrimSpace(s)
	if len(s) > max {
		s = s[:max]
	}
	// Strip control chars
	out := ""
	for _, c := range s {
		if c >= 0x20 && c != 0x7f {
			out += string(c)
		}
	}
	return out
}

// SetProfile upserts the caller's profile.
func SetProfile(cur realm, name, bio, uri string) {
	if !cur.Previous().IsUserCall() {
		panic("profile: EOA only")
	}
	ensure()
	name = sanitizeText(name, maxNameLen)
	bio = sanitizeText(bio, maxBioLen)
	uri = sanitizeText(uri, maxURILen)
	if name == "" {
		panic("profile: name required")
	}
	if uri != "" && !(strings.HasPrefix(uri, "https://") || strings.HasPrefix(uri, "http://") || strings.HasPrefix(uri, "ipfs://")) {
		panic("profile: uri must be http(s) or ipfs")
	}
	addr := cur.Previous().Address()
	p := &Profile{
		Name:    name,
		Bio:     bio,
		URI:     uri,
		Updated: runtime.ChainHeight(),
	}
	byAddr.Set(addr.String(), p)
	chain.Emit("SetProfile", "addr", addr.String(), "name", name)
}

// ClearProfile removes the caller's profile.
func ClearProfile(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("profile: EOA only")
	}
	ensure()
	addr := cur.Previous().Address().String()
	if byAddr.Has(addr) {
		byAddr.Remove(addr)
		chain.Emit("ClearProfile", "addr", addr)
	}
}

// GetProfile returns pipe-delimited: name|bio|uri|updatedHeight
// Empty string if none.
func GetProfile(addr string) string {
	ensure()
	addr = strings.TrimSpace(addr)
	if addr == "" {
		return ""
	}
	v := byAddr.Get(addr)
	if v == nil {
		return ""
	}
	p, ok := v.(*Profile)
	if !ok || p == nil {
		return ""
	}
	return p.Name + "|" + p.Bio + "|" + p.URI + "|" + strconv.FormatInt(p.Updated, 10)
}

// HasProfile reports whether addr has a profile.
func HasProfile(addr string) bool {
	ensure()
	return byAddr.Has(strings.TrimSpace(addr))
}

// ProfileCount returns number of profiles.
func ProfileCount() int {
	ensure()
	return byAddr.Size()
}

func sanitizeMD(s string) string {
	s = strings.ReplaceAll(s, "`", "'")
	s = strings.ReplaceAll(s, "<", "")
	s = strings.ReplaceAll(s, ">", "")
	return s
}

// Render home or user/{addr}
func Render(path string) string {
	path = strings.Trim(path, "/")
	ensure()
	if path == "" {
		out := "# gnomemepad profiles\n\n"
		out += "- Profiles: **" + strconv.Itoa(byAddr.Size()) + "**\n\n"
		out += "Call `SetProfile(name, bio, uri)` from your wallet.\n"
		return out
	}
	if strings.HasPrefix(path, "user/") {
		addr := strings.TrimPrefix(path, "user/")
		raw := GetProfile(addr)
		if raw == "" {
			return "> [!WARNING]\n> No profile for `" + sanitizeMD(addr) + "`\n"
		}
		parts := strings.SplitN(raw, "|", 4)
		name, bio, uri := parts[0], "", ""
		if len(parts) > 1 {
			bio = parts[1]
		}
		if len(parts) > 2 {
			uri = parts[2]
		}
		out := "# " + sanitizeMD(name) + "\n\n"
		out += "- Address: `" + sanitizeMD(addr) + "`\n"
		if bio != "" {
			out += "- Bio: " + sanitizeMD(bio) + "\n"
		}
		if uri != "" {
			out += "- URI: " + sanitizeMD(uri) + "\n"
		}
		return out
	}
	return "> [!WARNING]\n> Path not found\n"
}

func resetForTest() {
	byAddr = avl.Tree{}
	inited = false
}

// Package hubv2 is the multi-admin module router for gnomemepad (Phase 3F).
//
// Diff vs hub v1:
//   - Multiple admins (AddAdmin / RemoveAdmin / ListAdmins)
//   - Any admin may SetModule / TransferAdmin rights via AddAdmin
//   - Ops helpers: AdminCount, IsAdmin
//
// Migrate: deploy hubv2 → re-SetModule all paths → point UI HUB=hubv2
package hubv2

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

var (
	// admins: address string -> true
	admins avl.Tree
	inited bool
	// modules: name -> package path string
	modules avl.Tree
)

// Init sets the first admin (deployer EOA). Call once.
func Init(cur realm) {
	if inited {
		panic("hubv2: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("hubv2: EOA only")
	}
	a := cur.Previous().Address()
	admins = avl.Tree{}
	modules = avl.Tree{}
	admins.Set(a.String(), true)
	inited = true
	chain.Emit("Init", "admin", a.String())
}

func requireInit() {
	if !inited {
		panic("hubv2: call Init first")
	}
}

func isAdminAddr(addr address) bool {
	return admins.Has(addr.String())
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("hubv2: EOA only")
	}
	if !isAdminAddr(cur.Previous().Address()) {
		panic("hubv2: not admin")
	}
}

// IsAdmin reports whether addr is an admin.
func IsAdmin(addr string) bool {
	requireInit()
	return admins.Has(strings.TrimSpace(addr))
}

// AdminCount returns number of admins.
func AdminCount() int {
	requireInit()
	return admins.Size()
}

// ListAdmins returns newline-separated admin addresses.
func ListAdmins() string {
	requireInit()
	out := ""
	admins.Iterate("", "", func(key string, _ any) bool {
		if out != "" {
			out += "\n"
		}
		out += key
		return false
	})
	return out
}

// AddAdmin grants admin rights (existing admin only).
func AddAdmin(cur realm, newAdmin address) {
	requireAdmin(cur)
	if !newAdmin.IsValid() {
		panic("hubv2: invalid address")
	}
	if isAdminAddr(newAdmin) {
		panic("hubv2: already admin")
	}
	admins.Set(newAdmin.String(), true)
	chain.Emit("AddAdmin", "addr", newAdmin.String())
}

// RemoveAdmin revokes admin. Cannot remove last admin.
func RemoveAdmin(cur realm, who address) {
	requireAdmin(cur)
	if !who.IsValid() {
		panic("hubv2: invalid address")
	}
	if !isAdminAddr(who) {
		panic("hubv2: not an admin")
	}
	if admins.Size() <= 1 {
		panic("hubv2: cannot remove last admin")
	}
	// Prevent lock-out of caller if they're removing themselves as sole remaining — already size>1
	admins.Remove(who.String())
	chain.Emit("RemoveAdmin", "addr", who.String())
}

// SetModule registers or updates a module path (any admin).
func SetModule(cur realm, name, path string) {
	requireAdmin(cur)
	name = strings.TrimSpace(name)
	path = strings.TrimSpace(path)
	if name == "" || len(name) > 32 {
		panic("hubv2: invalid name")
	}
	if path == "" || len(path) > 200 {
		panic("hubv2: invalid path")
	}
	if !strings.HasPrefix(path, "gno.land/") {
		panic("hubv2: path must start with gno.land/")
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-') {
			panic("hubv2: name charset")
		}
	}
	modules.Set(name, path)
	chain.Emit("SetModule", "name", name, "path", path)
}

// GetModule returns the package path for name, or "".
func GetModule(name string) string {
	requireInit()
	v := modules.Get(name)
	if v == nil {
		return ""
	}
	s, ok := v.(string)
	if !ok {
		return ""
	}
	return s
}

// ListModules returns newline-separated "name|path".
func ListModules() string {
	requireInit()
	out := ""
	modules.Iterate("", "", func(key string, value any) bool {
		path, _ := value.(string)
		if out != "" {
			out += "\n"
		}
		out += key + "|" + path
		return false
	})
	return out
}

// ModuleCount for ops.
func ModuleCount() int {
	requireInit()
	return modules.Size()
}

// Inited reports Init.
func Inited() bool {
	return inited
}

// Admin returns first admin (compat) — first key in tree iteration order.
func Admin() string {
	requireInit()
	out := ""
	admins.Iterate("", "", func(key string, _ any) bool {
		out = key
		return true
	})
	return out
}

func Render(path string) string {
	path = strings.Trim(path, "/")
	if !inited {
		return "# gnomemepad hubv2\n\n> Not initialized.\n"
	}
	out := "# gnomemepad hubv2 (multi-admin)\n\n"
	out += "- Admins: **" + strconv.Itoa(admins.Size()) + "**\n"
	out += "- Modules: **" + strconv.Itoa(modules.Size()) + "**\n\n"
	out += "## Admins\n\n"
	admins.Iterate("", "", func(key string, _ any) bool {
		out += "- `" + key + "`\n"
		return false
	})
	out += "\n## Modules\n\n"
	modules.Iterate("", "", func(key string, value any) bool {
		p, _ := value.(string)
		out += "- **" + key + "**: `" + p + "`\n"
		return false
	})
	out += "\n## API\n\n- SetModule / GetModule / ListModules\n- AddAdmin / RemoveAdmin / ListAdmins / IsAdmin\n"
	_ = path
	return out
}

func resetForTest() {
	admins = avl.Tree{}
	modules = avl.Tree{}
	inited = false
}

// Package bond is the create-bond policy for gnomemepad — separate from pad
// so promo schedules can change without redeploying the pad realm.
//
// Pad calls CurrentBondUgnot() at Create time. This package owns:
//   - normal bond (default 2 GNOT)
//   - promo bond (default ~$20 in ugnot at a fixed GNOT rate, admin-adjustable)
//   - 10-day window OR admin EndPromo → back to normal
//
// USD is not on-chain: promo amount is ugnot. Admin sets PromoBondUgnot to
// approximate $20 (e.g. at $1/GNOT → 20e6 ugnot; at $0.5/GNOT → 40e6).
package bond

import (
	"chain"
	"strconv"
	"time"
)

const (
	DenomUgnot = "ugnot"

	// Defaults (ugnot, 1 GNOT = 1e6 ugnot)
	// Pearl / current policy: 100 GNOT create bond (admin can SetNormalBond).
	DefaultNormalBondUgnot int64 = 100_000_000 // 100 GNOT
	DefaultPromoBondUgnot  int64 = 100_000_000 // same unless StartPromo changes it
	DefaultPromoDuration   int64 = 10 * 24 * 60 * 60 // 10 days (seconds)

	// Status for UI
	StatusNormal = 0
	StatusPromo  = 1
)

var (
	inited bool
	admin  address

	normalBondUgnot int64
	promoBondUgnot  int64
	// promo: active while time.Now().Unix() < promoEndsAt and !promoEnded
	promoEndsAt int64
	promoEnded  bool // admin force-end (or auto after window)
	promoStartedAt int64
)

// Init sets admin (deploy EOA) and default bond amounts. Call once.
func Init(cur realm) {
	if inited {
		panic("bond: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("bond: EOA only")
	}
	admin = cur.Previous().Address()
	normalBondUgnot = DefaultNormalBondUgnot
	promoBondUgnot = DefaultPromoBondUgnot
	promoEndsAt = 0
	promoEnded = true
	promoStartedAt = 0
	inited = true
	chain.Emit("Init", "admin", admin.String())
}

func requireInit() {
	if !inited {
		panic("bond: call Init first")
	}
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("bond: EOA only")
	}
	if cur.Previous().Address() != admin {
		panic("bond: not admin")
	}
}

// Admin returns the admin (deploy) address.
func Admin() string {
	requireInit()
	return admin.String()
}

// TransferAdmin rotates admin (current admin only).
func TransferAdmin(cur realm, newAdmin address) {
	requireAdmin(cur)
	if !newAdmin.IsValid() {
		panic("bond: invalid address")
	}
	old := admin
	admin = newAdmin
	chain.Emit("TransferAdmin", "from", old.String(), "to", newAdmin.String())
}

// IsPromoActive reports whether the promo window is currently in force.
func IsPromoActive() bool {
	if !inited || promoEnded || promoEndsAt <= 0 {
		return false
	}
	now := time.Now().Unix()
	if now >= promoEndsAt {
		return false
	}
	return true
}

// CurrentBondUgnot is the create bond pad must require (cross-safe read).
// Pad: if sent < CurrentBondUgnot() → panic underpaid.
func CurrentBondUgnot() int64 {
	requireInit()
	if IsPromoActive() {
		return promoBondUgnot
	}
	return normalBondUgnot
}

// NormalBondUgnot returns the post-promo / default bond.
func NormalBondUgnot() int64 {
	requireInit()
	return normalBondUgnot
}

// PromoBondUgnot returns the promo-period bond amount (may be inactive).
func PromoBondUgnot() int64 {
	requireInit()
	return promoBondUgnot
}

// PromoEndsAt returns unix end of promo (0 if never started).
func PromoEndsAt() int64 {
	requireInit()
	return promoEndsAt
}

// PromoSecondsLeft returns remaining promo seconds (0 if inactive).
func PromoSecondsLeft() int64 {
	if !IsPromoActive() {
		return 0
	}
	left := promoEndsAt - time.Now().Unix()
	if left < 0 {
		return 0
	}
	return left
}

// Status: 0=normal 1=promo active.
func Status() int {
	if IsPromoActive() {
		return StatusPromo
	}
	return StatusNormal
}

// BondInfo: status|currentUgnot|normalUgnot|promoUgnot|endsAt|secondsLeft|admin
func BondInfo() string {
	requireInit()
	st := Status()
	return strconv.Itoa(st) + "|" +
		strconv.FormatInt(CurrentBondUgnot(), 10) + "|" +
		strconv.FormatInt(normalBondUgnot, 10) + "|" +
		strconv.FormatInt(promoBondUgnot, 10) + "|" +
		strconv.FormatInt(promoEndsAt, 10) + "|" +
		strconv.FormatInt(PromoSecondsLeft(), 10) + "|" +
		admin.String()
}

// StartPromo begins a promo window from now.
// promoUgnot: bond during promo (e.g. 20e6 ≈ $20 at $1/GNOT). 0 → keep current promoBondUgnot.
// durationSec: window length. 0 → DefaultPromoDuration (10 days).
func StartPromo(cur realm, promoUgnot, durationSec int64) {
	requireAdmin(cur)
	if promoUgnot < 0 {
		panic("bond: promoUgnot must be non-negative")
	}
	if promoUgnot > 0 {
		promoBondUgnot = promoUgnot
	}
	if promoBondUgnot <= 0 {
		panic("bond: set promo bond amount first")
	}
	if durationSec <= 0 {
		durationSec = DefaultPromoDuration
	}
	now := time.Now().Unix()
	promoStartedAt = now
	promoEndsAt = now + durationSec
	promoEnded = false
	chain.Emit("StartPromo",
		"promoUgnot", strconv.FormatInt(promoBondUgnot, 10),
		"endsAt", strconv.FormatInt(promoEndsAt, 10),
		"durationSec", strconv.FormatInt(durationSec, 10),
	)
}

// EndPromo forces normal bond immediately (deploy admin).
func EndPromo(cur realm) {
	requireAdmin(cur)
	promoEnded = true
	// keep promoEndsAt for history
	chain.Emit("EndPromo",
		"at", strconv.FormatInt(time.Now().Unix(), 10),
		"normalUgnot", strconv.FormatInt(normalBondUgnot, 10),
	)
}

// SetNormalBond updates the post-promo bond (default 2 GNOT).
func SetNormalBond(cur realm, ugnot int64) {
	requireAdmin(cur)
	if ugnot <= 0 {
		panic("bond: normal bond must be positive")
	}
	normalBondUgnot = ugnot
	chain.Emit("SetNormalBond", "ugnot", strconv.FormatInt(ugnot, 10))
}

// SetPromoBond updates promo amount without restarting the clock.
// Use to re-target ~$20 when GNOT price moves during the window.
func SetPromoBond(cur realm, ugnot int64) {
	requireAdmin(cur)
	if ugnot <= 0 {
		panic("bond: promo bond must be positive")
	}
	promoBondUgnot = ugnot
	chain.Emit("SetPromoBond", "ugnot", strconv.FormatInt(ugnot, 10))
}

// ExtendPromo adds seconds to the current end (or starts from now if inactive).
func ExtendPromo(cur realm, extraSec int64) {
	requireAdmin(cur)
	if extraSec <= 0 {
		panic("bond: extraSec must be positive")
	}
	now := time.Now().Unix()
	if !IsPromoActive() {
		// restart promo with current promoBondUgnot
		promoStartedAt = now
		promoEndsAt = now + extraSec
		promoEnded = false
	} else {
		promoEndsAt += extraSec
		promoEnded = false
	}
	chain.Emit("ExtendPromo",
		"endsAt", strconv.FormatInt(promoEndsAt, 10),
		"extraSec", strconv.FormatInt(extraSec, 10),
	)
}

package bond

import (
	"strconv"

	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	_ = path
	out := "# gnomemepad create-bond policy\n\n"
	out += "Separate realm — pad upgrades do not replace this schedule.\n\n"
	if !inited {
		out += "> [!CAUTION]\n> Call Init first.\n"
		return out
	}
	out += ufmt.Sprintf("- **Current bond:** %d ugnot (~%d GNOT)\n", CurrentBondUgnot(), CurrentBondUgnot()/1_000_000)
	out += ufmt.Sprintf("- **Normal bond:** %d ugnot\n", normalBondUgnot)
	out += ufmt.Sprintf("- **Promo bond:** %d ugnot\n", promoBondUgnot)
	if IsPromoActive() {
		out += ufmt.Sprintf("- **Promo active** — ends at unix %d (~%d s left)\n", promoEndsAt, PromoSecondsLeft())
	} else {
		out += "- Promo: inactive (using normal bond)\n"
	}
	out += ufmt.Sprintf("- Admin: `%s`\n\n", admin.String())
	out += "## API\n\n"
	out += "- `CurrentBondUgnot()` — pad reads this on Create\n"
	out += "- `StartPromo(promoUgnot, durationSec)` — admin; 0 amount keeps set promo bond; 0 duration → 10d\n"
	out += "- `EndPromo()` — admin → normal bond immediately\n"
	out += "- `SetNormalBond` / `SetPromoBond` / `ExtendPromo`\n"
	out += "- `BondInfo()` → status|current|normal|promo|endsAt|left|admin\n"
	_ = strconv.Itoa(0)
	return out
}

// Package meta stores off-pad token presentation data (description, image, socials).
// Independent of pad versions â€” upgrade without redeploying markets.
//
// Key = padPkg + "|" + launchId
// First SetMeta caller becomes owner; only owner may update later.
package meta

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	maxDescLen    = 500
	maxURILen     = 200
	maxHandleLen  = 64
	maxPadPathLen = 200
	maxLaunchId   = 32
)

// TokenMeta is presentation data for one launch (not trading state).
type TokenMeta struct {
	PadPkg      string
	LaunchID    string
	Owner       address
	Description string
	ImageURI    string
	Website     string
	Twitter     string
	Telegram    string
	Updated     int64
}

var (
	// byKey: pad|id -> *TokenMeta
	byKey  avl.Tree
	inited bool
)

func Init(cur realm) {
	if inited {
		panic("meta: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("meta: EOA only")
	}
	inited = true
	byKey = avl.Tree{}
	chain.Emit("Init", "by", cur.Previous().Address().String())
}

func ensure() {
	if !inited {
		byKey = avl.Tree{}
		inited = true
	}
}

func makeKey(padPkg, launchID string) string {
	return padPkg + "|" + launchID
}

func sanitizeText(s string, max int) string {
	s = strings.TrimSpace(s)
	if len(s) > max {
		s = s[:max]
	}
	out := ""
	for _, c := range s {
		if c >= 0x20 && c != 0x7f {
			out += string(c)
		}
	}
	return out
}

func validateURI(uri string) {
	if uri == "" {
		return
	}
	if !(strings.HasPrefix(uri, "https://") || strings.HasPrefix(uri, "http://") || strings.HasPrefix(uri, "ipfs://")) {
		panic("meta: uri must be http(s) or ipfs")
	}
}

func validatePadPkg(padPkg string) {
	padPkg = strings.TrimSpace(padPkg)
	if padPkg == "" || len(padPkg) > maxPadPathLen {
		panic("meta: invalid pad path")
	}
	if !strings.HasPrefix(padPkg, "gno.land/r/") {
		panic("meta: pad must be gno.land/r/â€¦")
	}
}

// SetMeta upserts metadata for a launch. First writer owns the entry.
func SetMeta(cur realm, padPkg, launchID, description, imageURI, website, twitter, telegram string) {
	if !cur.Previous().IsUserCall() {
		panic("meta: EOA only")
	}
	ensure()
	validatePadPkg(padPkg)
	launchID = sanitizeText(launchID, maxLaunchId)
	if launchID == "" {
		panic("meta: launch id required")
	}
	description = sanitizeText(description, maxDescLen)
	imageURI = sanitizeText(imageURI, maxURILen)
	website = sanitizeText(website, maxURILen)
	twitter = sanitizeText(twitter, maxHandleLen)
	telegram = sanitizeText(telegram, maxHandleLen)
	validateURI(imageURI)
	validateURI(website)

	key := makeKey(padPkg, launchID)
	caller := cur.Previous().Address()
	existing := byKey.Get(key)
	if existing != nil {
		tm := existing.(*TokenMeta)
		if tm.Owner != caller {
			panic("meta: not owner")
		}
		tm.Description = description
		tm.ImageURI = imageURI
		tm.Website = website
		tm.Twitter = twitter
		tm.Telegram = telegram
		tm.Updated = runtime.ChainHeight()
		byKey.Set(key, tm)
	} else {
		tm := &TokenMeta{
			PadPkg:      padPkg,
			LaunchID:    launchID,
			Owner:       caller,
			Description: description,
			ImageURI:    imageURI,
			Website:     website,
			Twitter:     twitter,
			Telegram:    telegram,
			Updated:     runtime.ChainHeight(),
		}
		byKey.Set(key, tm)
	}
	chain.Emit("SetMeta", "key", key, "owner", caller.String())
}

// GetMeta returns:
//
//	owner|description|imageURI|website|twitter|telegram|updated
//
// Empty string if none.
func GetMeta(padPkg, launchID string) string {
	ensure()
	key := makeKey(strings.TrimSpace(padPkg), strings.TrimSpace(launchID))
	v := byKey.Get(key)
	if v == nil {
		return ""
	}
	tm := v.(*TokenMeta)
	return tm.Owner.String() + "|" +
		tm.Description + "|" +
		tm.ImageURI + "|" +
		tm.Website + "|" +
		tm.Twitter + "|" +
		tm.Telegram + "|" +
		strconv.FormatInt(tm.Updated, 10)
}

// HasMeta reports whether metadata exists.
func HasMeta(padPkg, launchID string) bool {
	ensure()
	return byKey.Has(makeKey(strings.TrimSpace(padPkg), strings.TrimSpace(launchID)))
}

// MetaCount returns number of entries.
func MetaCount() int {
	ensure()
	return byKey.Size()
}

// ClearMeta removes caller's owned entry.
func ClearMeta(cur realm, padPkg, launchID string) {
	if !cur.Previous().IsUserCall() {
		panic("meta: EOA only")
	}
	ensure()
	key := makeKey(strings.TrimSpace(padPkg), strings.TrimSpace(launchID))
	v := byKey.Get(key)
	if v == nil {
		return
	}
	tm := v.(*TokenMeta)
	if tm.Owner != cur.Previous().Address() {
		panic("meta: not owner")
	}
	byKey.Remove(key)
	chain.Emit("ClearMeta", "key", key)
}

func sanitizeMD(s string) string {
	s = strings.ReplaceAll(s, "`", "'")
	s = strings.ReplaceAll(s, "<", "")
	s = strings.ReplaceAll(s, ">", "")
	return s
}

func Render(path string) string {
	path = strings.Trim(path, "/")
	ensure()
	if path == "" {
		return "# gnomemepad meta\n\n- Entries: **" + strconv.Itoa(byKey.Size()) + "**\n\n" +
			"SetMeta(padPkg, launchID, description, imageURI, website, twitter, telegram)\n"
	}
	return "> [!WARNING]\n> Path not found: " + sanitizeMD(path) + "\n"
}

